#!/usr/bin/env python3
"""J10 blind re-derivation: Q3, QM, QB, QNF (and Q0 sensitivity figures).

Closed-form arithmetic only (BL-6): exact integers (math.comb) and exact
rationals (fractions.Fraction) wherever possible; logarithms in mpmath at 60
significant digits. No curve, no solver, no walk.

Model, as derived from Semaev 2015 (paper lines cited in the report):
  k        = n/m (KR-A, real)  |  ceil(n/m) (KR-B)
  P        = 2^(mk - n) / m!          (Section 4.5.2, lines 1066-1067)  [primary]
  P_eq11   = 1 - exp(-2^(mk - n)/m!)   (Section 4.3, eq. (11), lines 407-417) [Q0 alternative]
  A(n, m)  = log2(2^k) + log2(1/P) = k + n - m k + log2(m!)            (eq. (15), lines 1074-1086)
  W(N, D)  = log2 sum_{d=0..D} binom(N, d)
  S_B      = D omega log2 n ; S_M = omega (W(n,D) - W(n,4) + 4 log2 n)
  C_R      = A + S_R ; rho(c) from q1_out.json (r, k_c)
  N5(n,t,k)= (t - 2) n + t k        (lines 611-613, 367-372)
"""
import functools
import json
import math
import sys
from fractions import Fraction as Fr

import mpmath as mp

mp.mp.dps = 60
OMEGA = Fr(3)            # PIN-OMEGA, omega = 3.0
OMEGA_MP = mp.mpf(3)
M_GRID = list(range(2, 31))
D_GRID = list(range(2, 65))
