# ------------------------------------------------------------------ helpers
def ceil_div(a, b):
    return -(-a // b)


def frac_ceil(x):
    x = Fr(x)
    return -((-x.numerator) // x.denominator)


def frac_floor(x):
    x = Fr(x)
    return x.numerator // x.denominator


def frac_nearest(x):           # halves up; no half-integer ever occurs here
    return frac_floor(Fr(x) + Fr(1, 2))


def to_mp(x):
    if isinstance(x, Fr):
        return mp.mpf(x.numerator) / x.denominator
    return mp.mpf(x)


def log2(x):
    return mp.log(to_mp(x), 2)


def f(x, nd=6):
    return float(round(float(x), nd))


def gbinom(N, d):
    """binom(N, d) for integer d >= 0 and N an int or Fraction (generalised)."""
    if isinstance(N, int) or (isinstance(N, Fr) and N.denominator == 1):
        return math.comb(int(N), d)
    num = Fr(1)
    for i in range(d):
        num *= (N - i)
    return num / math.factorial(d)


@functools.lru_cache(maxsize=None)
def W(N, D):
    return log2(sum(gbinom(N, d) for d in range(0, D + 1)))


def k_of(n, m, kr):
    return Fr(n, m) if kr == 'KR-A' else ceil_div(n, m)


def log2_inv_P(n, m, kr, pform='4.5.2'):
    k = k_of(n, m, kr)
    e = m * k - n                         # exponent of 2 in |V|^m / q
    if pform == '4.5.2':
        return to_mp(-e) + log2(math.factorial(m))
    x = mp.power(2, to_mp(e)) / math.factorial(m)
    return -mp.log(1 - mp.exp(-x), 2)


def A(n, m, kr, pform='4.5.2'):
    return to_mp(k_of(n, m, kr)) + log2_inv_P(n, m, kr, pform)


def S_B(n, D):
    return D * OMEGA_MP * log2(n)


def S_M(n, D):
    return OMEGA_MP * (W(n, D) - W(n, 4) + 4 * log2(n))


def N5(n, t, k):
    return (t - 2) * n + t * k


def N5_roundings(n, t, kr, m):
    k = k_of(n, m, kr)
    x = N5(n, t, k)
    xf = Fr(x)
    return {'unrounded': xf, 'nearest': frac_nearest(xf), 'ceil': frac_ceil(xf)}


def num(k):
    k = Fr(k)
    return int(k) if k.denominator == 1 else f(to_mp(k))


def fr_str(x):
    x = Fr(x)
    return str(x.numerator) if x.denominator == 1 else f'{x.numerator}/{x.denominator}'


