# ------------------------------------------------------------------ Q3
def threshold_row(c, R, kr, m, pform='4.5.2'):
    a = A(571, m, kr, pform)
    S = S_B if R == 'R-B' else S_M
    margin = {D: a + S(571, D) - RHO[c] for D in range(1, 65)}
    dstar = next((D for D in D_GRID if margin[D] > 0), None)
    row = {'c': c, 'R': R, 'k_reading': kr, 'm': m, 'A_571_m': f(a)}
    if dstar is None:
        row['D_star'] = 'no crossing at D <= 64'
        row['margin_at_D64'] = f(margin[64])
    elif dstar == 2:
        row['D_star'] = 'D* <= 2'
        row['margin_at_D_star_minus_1'] = 'not defined: D = 1 is outside the grid 2..64'
        row['margin_at_D2'] = f(margin[2])
    else:
        row['D_star'] = dstar
        row['margin_at_D_star_minus_1'] = f(margin[dstar - 1])
        row['margin_at_D_star'] = f(margin[dstar])
    if R == 'R-B':
        dreal = (RHO[c] - a) / (OMEGA_MP * log2(571))
        row['D_star_real_B'] = float(round(float(dreal), 2))
        row['D_star_real_B_4dp'] = f(dreal, 4)
        # consistency: integer threshold == least integer D in 2..64 with D > dreal
        if dstar is not None:
            expect = max(2, frac_floor(Fr(str(mp.nstr(dreal, 40)))) + 1)
            row['_check_integer_vs_real'] = (expect == dstar) or (dstar == 2 and expect <= 2)
    row['relation_store_k'] = num(k_of(571, m, kr))
    return row, dstar


def compute_Q3():
    rows, alt_changes = [], []
    for c in ('K-571', 'B-571'):
        for R in ('R-B', 'R-M'):
            for kr in ('KR-A', 'KR-B'):
                for m in M_GRID:
                    row, d1 = threshold_row(c, R, kr, m)
                    rows.append(row)
                    _, d2 = threshold_row(c, R, kr, m, pform='eq11')
                    if d1 != d2:
                        alt_changes.append({'c': c, 'R': R, 'k_reading': kr, 'm': m,
                                            'D_star_4.5.2': d1, 'D_star_eq11': d2})
    return rows, alt_changes


# ------------------------------------------------------------------ QM
def qm_point(n, m, t, D, kr, extra_D=None):
    """Every QM column at (n, m, t, D, k reading). Both relation-store
    definitions; MR_F4 monomial form (amendment); every N5 rounding."""
    k = k_of(n, m, kr)
    l = ceil_div(n, m)
    nvar = m * l
    out = {'n': n, 'm': m, 't': t, 'D': D, 'k_reading': kr, 'k': fr_str(k), 'k_value': num(k)}
    rr = N5_roundings(n, t, kr, m)
    out['N5'] = {'unrounded': fr_str(rr['unrounded']), 'nearest': rr['nearest'], 'ceil': rr['ceil']}
    out['MR_B'] = f(D * log2(n))
    out['MR_M'] = f(W(n, D))
    out['MR_F4'] = f(D * log2(n * (t - 1))) if t >= 2 else None
    out['MR_F4_monomial_W(n(t-1),D)'] = f(W(n * (t - 1), D))
    mac = {}
    for key in ('unrounded', 'nearest', 'ceil'):
        mac[key] = f(W(rr[key], D))
    out['MR_MAC'] = mac
    out['MR_C8'] = f(log2(math.comb(nvar, D)))
    out['MR_C8_nvar'] = nvar
    out['dense'] = {
        'MR_B': f(2 * D * log2(n)), 'MR_M': f(2 * W(n, D)),
        'MR_F4': f(2 * D * log2(n * (t - 1))), 'MR_F4_monomial': f(2 * W(n * (t - 1), D)),
        'MR_MAC': {key: f(2 * W(rr[key], D)) for key in ('unrounded', 'nearest', 'ceil')},
        'MR_C8': f(2 * log2(math.comb(nvar, D))),
    }
    out['relation_store'] = {'blind_inputs_log2_k': f(log2(k)), 'amendment_k_log2_count': f(to_mp(k))}
    return out


def compute_QM():
    d4 = []
