# ------------------------------------------------------------------ QB
def compute_QB():
    rows = []
    for m in M_GRID:
        for kr in ('KR-A', 'KR-B'):
            rr = N5_roundings(571, m, kr, m)
            for key in ('unrounded', 'nearest', 'ceil'):
                N = rr[key]
                w4 = W(N, 4)
                delta = {D: (W(N, D) - w4) - (D - 4) * log2(571) for D in range(4, 65)}
                neg = next((D for D in range(5, 65) if delta[D] < 0), None)
                mx = max(delta.values())
                arg = min(D for D in range(4, 65) if delta[D] == mx)
                mx5 = max(delta[D] for D in range(5, 65))
                arg5 = min(D for D in range(5, 65) if delta[D] == mx5)
                rows.append({'m': m, 'k_reading': kr, 'N5_rounding': key, 'N5': fr_str(N), 'reading': 'M7-BIN',
                             'least_D_ge5_DELTA7_neg': neg if neg is not None else 'none in 5..64',
                             'max_DELTA7_over_D4to64': f(mx), 'argmax_D': arg,
                             'max_DELTA7_over_D5to64': f(mx5), 'argmax_D_over_5to64': arg5,
                             'DELTA7_by_D': {D: f(v) for D, v in delta.items()}})
    return rows


# ------------------------------------------------------------------ C_I and NF items
def C_I(n, kr, pform='4.5.2'):
    vals = []
    for m in range(2, min(30, n) + 1):
        vals.append((A(n, m, kr, pform) + 4 * OMEGA_MP * log2(n), m))
    best_v, best_m = vals[0]
    for v, m in vals[1:]:
        if v < best_v:                                  # first minimum, ascending m, strict <
            best_v, best_m = v, m
    # runner-up: second in (value, m) order, ties to the lower m; exact ties detected at 1e-40
    srt = sorted(vals, key=lambda vm: (mp.nint(vm[0] * mp.mpf(10) ** 40), vm[1]))
    ties = [(a_[1], b_[1]) for a_, b_ in zip(srt, srt[1:]) if abs(a_[0] - b_[0]) < mp.mpf('1e-40')]
    assert srt[0][1] == best_m, (n, kr, srt[0], best_m)
    run_v, run_m = srt[1]
    return {'C_I': best_v, 'argmin': best_m, 'runner_up_m': run_m, 'runner_up_value': run_v,
            'gap': run_v - best_v, 'exact_ties_detected': ties}


NF05_DEGREES = [79, 89, 97, 109, 131, 155, 163, 185, 191, 233, 239, 283, 359, 409, 571]


def nf05_item(n):
