        c = ci[kr]
        ms = c['argmin']
        nvar = ms * ceil_div(n, ms)
        k_ms = k_of(n, ms, kr)
        k_ru = k_of(n, c['runner_up_m'], kr)
        out[lab] = {
            '(a)_C_I': f(c['C_I']), '(a)_argmin_m_star': ms,
            '(b)_runner_up_m': c['runner_up_m'], '(b)_runner_up_value': f(c['runner_up_value']),
            '(b)_gap': f(c['gap']), 'exact_ties_detected': c['exact_ties_detected'],
            '(c)_MR_B': f(4 * log2(n)), '(c)_MR_M': f(W(n, 4)),
            '(c)_MR_C8': f(log2(math.comb(nvar, 4))), '(c)_nvar': nvar,
            '(c)_dense_2MR_B': f(8 * log2(n)), '(c)_dense_2MR_M': f(2 * W(n, 4)),
            '(c)_dense_2MR_C8': f(2 * log2(math.comb(nvar, 4))),
            '(c)_relation_store_k_at_m_star': num(k_ms),
            '(d)_relation_store_k_at_runner_up': num(k_ru),
        }
    move = ci['KR-B']['C_I'] - ci['KR-A']['C_I']
    out['(e)_move_ceiled_minus_MI-1'] = f(move)
    out['(e)_sign'] = 'negative' if move < 0 else ('positive' if move > 0 else 'zero')
    return out, ci


