            xp['XP-1'].append(p)
            ru = c['runner_up_m']
            k = k_of(n, ru, kr)
            rr = N5_roundings(n, ru, kr, ru)
            xp['XP-2'].append({'n': n, 'k_reading': kr, 'm_runner_up': ru, 't': ru,
                               'relation_store': {'blind_inputs_log2_k': f(log2(k)), 'amendment_k_log2_count': f(to_mp(k))},
                               'k': fr_str(k),
                               'N5_supplementary': {'unrounded': fr_str(rr['unrounded']), 'nearest': rr['nearest'], 'ceil': rr['ceil']}})
    xp['XP-3'] = {'n': 409, 'D': 5, 'MR_B': f(5 * log2(409)), 'MR_M': f(W(409, 5)),
                  'dense_2MR_B': f(10 * log2(409)), 'dense_2MR_M': f(2 * W(409, 5))}
    ms = ci_all[571]['KR-A']['argmin']
    for D in (2, 3):
        p = qm_point(571, ms, ms, D, 'KR-A')
        p['m_rule'] = 'KR-A argmin m* of C_I(571, 3.0)'
        xp['XP-4'].append(p)
    t283 = ci_all[283]['KR-A']['argmin']
    nv = t283 * (283 // t283)
    xp['supplementary_columns_outside_qm']['n283_floor_sizing_D4'] = {
        't': t283, 'nvar': nv, 'log2_binom(nvar,4)': f(log2(math.comb(nv, 4)))}
    nv571 = ms * ceil_div(571, ms)
    xp['supplementary_columns_outside_qm']['n571_power_form_D_log2_nvar_D4'] = {
        't': ms, 'nvar': nv571, 'D_log2_nvar': f(4 * log2(nv571))}
    xp['supplementary_columns_outside_qm']['NF08_point_f4_std_monomial_W(n(t-1),4)'] = f(W(571 * 9, 4))
    return xp


def q0_sensitivity():
    out = {'A_eq11_minus_A_4.5.2_at_n571': []}
    for kr in ('KR-A', 'KR-B'):
        for m in M_GRID:
            d = A(571, m, kr, 'eq11') - A(571, m, kr)
            out['A_eq11_minus_A_4.5.2_at_n571'].append({'k_reading': kr, 'm': m, 'delta_bits': f(d)})
    # MR_C8 with l = n/m under KR-A (nvar = n) vs pinned l = ceil(n/m): D = 4, n in QM grid
    alt = []
    for n in (571, 283, 359, 409):
        for m in M_GRID:
            nv = m * ceil_div(n, m)
            alt.append({'n': n, 'm': m, 'MR_C8_pinned_nvar': nv, 'MR_C8_pinned': f(log2(math.comb(nv, 4))),
                        'MR_C8_if_nvar_eq_n': f(log2(math.comb(n, 4))),
                        'diff': f(log2(math.comb(nv, 4)) - log2(math.comb(n, 4)))})
    out['MR_C8_D4_alternative_nvar_eq_n'] = alt
    return out


def main():
    q3, q3_alt = compute_Q3()
    d4, dtab = compute_QM()
    qb = compute_QB()
    nf, ci_all, ci_alt = compute_NF()
    xp = compute_XP(ci_all)
    sens = q0_sensitivity()
    sens['Q3_D_star_changes_under_eq11'] = q3_alt
    sens['C_I_under_eq11'] = ci_alt
    out = {
        'rho': {c: mp.nstr(RHO[c], 15) for c in RHO},
        'A_571': [{'m': m, 'KR-A': f(A(571, m, 'KR-A')), 'KR-B': f(A(571, m, 'KR-B')),
                   'KR-A_exact_form': f'571/{m} + log2({m}!)',
                   'KR-B_exact_form': f'{571 - (m - 1) * ceil_div(571, m)} + log2({m}!)'} for m in M_GRID],
        'W_571_4': f(W(571, 4)),
        'Q3': q3, 'QM_D4': d4, 'QM_Dtables_571': dtab, 'QB': qb,
        'QNF': nf, 'QM_extra_points': xp, 'Q0_sensitivity': sens,
        'versions': {'python': sys.version.split()[0], 'mpmath': mp.__version__, 'mp_dps': mp.mp.dps},
    }
    with open(HERE + 'j10_raw.json', 'w') as fh:
        json.dump(out, fh, indent=1, default=str)
    print('Q3 rows', len(q3), '| QM D4 rows', len(d4), '| QB rows', len(qb))
    print('rho', out['rho'])
    print('Q3 D* changes under eq11:', len(q3_alt))
    chk = [r for r in q3 if r.get('_check_integer_vs_real') is False]
    print('R-B integer-vs-real inconsistencies:', len(chk))


