#!/usr/bin/env python3
"""Disjoint arithmetic checker for j10_compute.py.

Shares no numeric code with j10_compute.py: Python's decimal module at 60
digits, pi from Machin's formula implemented here, logarithms by
Decimal.ln(); no mpmath, no fractions. Every Q3, QB, QM (D = 4) and C_I cell
is recomputed from the definitions and compared with j10_raw.json.
"""
import json
import math
from decimal import Decimal as Dec, getcontext

getcontext().prec = 60
HERE = '/tmp/claude-0/-home-user/f42055f8-3588-569d-b7d9-926d696d2468/scratchpad/BATCH-f435ab/TASK-20261002-84c5d6/'
LN2 = Dec(2).ln()


def atan_inv(x):
    """arctan(1/x) by its Taylor series, x a positive int."""
    x = Dec(x)
    x2 = x * x
    term = 1 / x
    total = term
    n = 1
    eps = Dec(10) ** (-(getcontext().prec + 2))
    while True:
        term = -term / x2
        n += 2
        t = term / n
        if abs(t) < eps:
            break
        total += t
    return total


PI = 16 * atan_inv(5) - 4 * atan_inv(239)


def lg(x):                       # x: int or Decimal > 0
    return Dec(x).ln() / LN2


def cdiv(a, b):
    return -(-a // b)


def A(n, m, kr):
    if kr == 'KR-A':
        return Dec(n) / Dec(m) + lg(math.factorial(m))
    k = cdiv(n, m)
    return Dec(k + n - m * k) + lg(math.factorial(m))


def W(N, D):
    return lg(sum(math.comb(N, d) for d in range(D + 1)))


def N5(n, t, m, kr):
    if kr == 'KR-A':
        num = (t - 2) * n * m + t * n          # (t-2) n + t n/m, times m
        assert num % m == 0                     # true at every evaluated point (t = m)
        return num // m
    return (t - 2) * n + t * cdiv(n, m)


def main():
    raw = json.load(open(HERE + 'j10_raw.json'))
    q1 = json.load(open(HERE + 'q1_out.json'))['results']
    rho = {c: Dec('0.5') * lg(PI * Dec(int(q1[c]['r_decimal'])) / (4 * q1[c]['k_c'])) for c in ('K-571', 'B-571')}
    rep = {'rho_decimal': {c: str(+rho[c])[:22] for c in rho},
           'rho_abs_diff_vs_mpmath': {c: float(abs(rho[c] - Dec(raw['rho'][c]))) for c in rho}}
    L571 = lg(571)
    w4 = W(571, 4)
    # ---- Q3
    mism, maxd = [], Dec(0)
    for row in raw['Q3']:
        c, R, kr, m = row['c'], row['R'], row['k_reading'], row['m']
        a = A(571, m, kr)
        maxd = max(maxd, abs(a - Dec(str(row['A_571_m']))))
        if R == 'R-B':
            marg = {D: a + D * 3 * L571 - rho[c] for D in range(1, 65)}
        else:
            marg = {D: a + 3 * (W(571, D) - w4 + 4 * L571) - rho[c] for D in range(1, 65)}
        ds = next((D for D in range(2, 65) if marg[D] > 0), None)
        tok = 'no crossing at D <= 64' if ds is None else ('D* <= 2' if ds == 2 else ds)
        if tok != row['D_star']:
            mism.append((c, R, kr, m, tok, row['D_star']))
        if isinstance(tok, int):
            maxd = max(maxd, abs(marg[tok] - Dec(str(row['margin_at_D_star']))),
                       abs(marg[tok - 1] - Dec(str(row['margin_at_D_star_minus_1']))))
        if R == 'R-B':
            dreal = (rho[c] - a) / (3 * L571)
            maxd = max(maxd, abs(dreal - Dec(str(row['D_star_real_B_4dp']))))
    rep['Q3'] = {'rows': len(raw['Q3']), 'threshold_mismatches': mism,
                 'max_abs_diff_A_margins_Dreal_(rounding_of_reported_values_included)': float(maxd)}
    # ---- QB
    mism, maxd = [], Dec(0)
    for row in raw['QB']:
        m, kr = row['m'], row['k_reading']
        N = N5(571, m, m, kr)
        assert str(N) == row['N5'], (m, kr, N, row['N5'])
        wn4 = W(N, 4)
        delta = {D: (W(N, D) - wn4) - (D - 4) * L571 for D in range(4, 65)}
        neg = next((D for D in range(5, 65) if delta[D] < 0), 'none in 5..64')
        mx = max(delta.values())
        arg = min(D for D in delta if delta[D] == mx)
        if neg != row['least_D_ge5_DELTA7_neg'] or arg != row['argmax_D']:
            mism.append((m, kr, row['N5_rounding'], neg, row['least_D_ge5_DELTA7_neg'], arg, row['argmax_D']))
        for D in range(4, 65):
            maxd = max(maxd, abs(delta[D] - Dec(str(row['DELTA7_by_D'][str(D)]))))
    rep['QB'] = {'rows': len(raw['QB']), 'mismatches': mism, 'max_abs_diff_DELTA7': float(maxd)}
    # ---- QM at D = 4
    maxd, nbad = Dec(0), 0
    for p in raw['QM_D4']:
        n, m, kr = p['n'], p['m'], p['k_reading']
        N = N5(n, m, m, kr)
        if not (str(N) == p['N5']['unrounded'] and N == p['N5']['nearest'] == p['N5']['ceil']):
            nbad += 1
        nvar = m * cdiv(n, m)
        k = Dec(n) / Dec(m) if kr == 'KR-A' else Dec(cdiv(n, m))
        checks = [(4 * lg(n), p['MR_B']), (W(n, 4), p['MR_M']), (4 * lg(n * (m - 1)), p['MR_F4']),
                  (W(n * (m - 1), 4), p['MR_F4_monomial_W(n(t-1),D)']), (W(N, 4), p['MR_MAC']['nearest']),
                  (lg(math.comb(nvar, 4)), p['MR_C8']), (k.ln() / LN2, p['relation_store']['blind_inputs_log2_k']),
                  (k, p['relation_store']['amendment_k_log2_count'])]
        for v, ref in checks:
            maxd = max(maxd, abs(v - Dec(str(ref))))
        if nvar != p['MR_C8_nvar']:
            nbad += 1
    rep['QM_D4'] = {'rows': len(raw['QM_D4']), 'integer_mismatches': nbad, 'max_abs_diff_log2_columns': float(maxd)}
    # ---- C_I argmin / runner-up for every NF-05 degree and reading
    mism = []
    for it in raw['QNF']['NF-05']:
        n = it['n']
        for kr, lab in (('KR-A', 'MI-1'), ('KR-B', 'ceiled')):
            vals = [(A(n, m, kr) + 12 * lg(n), m) for m in range(2, min(30, n) + 1)]
            best = vals[0]
            for v in vals[1:]:
                if v[0] < best[0]:
                    best = v
            srt = sorted(vals, key=lambda vm: (vm[0].quantize(Dec('1e-40')), vm[1]))
            if best[1] != it[lab]['(a)_argmin_m_star'] or srt[1][1] != it[lab]['(b)_runner_up_m']:
                mism.append((n, kr, best[1], srt[1][1]))
    rep['C_I'] = {'cells': 2 * len(raw['QNF']['NF-05']), 'argmin_or_runner_up_mismatches': mism}
    print(json.dumps(rep, indent=1, default=str))


if __name__ == '__main__':
    main()
